CREATE TABLE `VaultReferralAccount` (`userId` VARCHAR(191) NOT NULL, `code` VARCHAR(24) NOT NULL, `bonusAwardedAt` DATETIME(3) NULL, `celebrationSeenAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `VaultReferralAccount_code_key`(`code`), PRIMARY KEY (`userId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `VaultReferral` (`id` VARCHAR(191) NOT NULL, `referrerUserId` VARCHAR(191) NOT NULL, `referredUserId` VARCHAR(191) NOT NULL, `completedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `VaultReferral_referredUserId_key`(`referredUserId`), INDEX `VaultReferral_referrerUserId_completedAt_idx`(`referrerUserId`, `completedAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `VaultStoragePlan` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(100) NOT NULL, `capacityBytes` BIGINT NOT NULL, `interval` VARCHAR(16) NOT NULL, `priceCents` INTEGER NULL, `currency` VARCHAR(3) NOT NULL DEFAULT 'USD', `appleProductId` VARCHAR(191) NULL, `googleProductId` VARCHAR(191) NULL, `active` BOOLEAN NOT NULL DEFAULT false, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `VaultStoragePlan_appleProductId_key`(`appleProductId`), UNIQUE INDEX `VaultStoragePlan_googleProductId_key`(`googleProductId`), UNIQUE INDEX `VaultStoragePlan_capacityBytes_interval_key`(`capacityBytes`, `interval`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `VaultStorageEntitlement` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `planId` VARCHAR(191) NOT NULL, `capacityBytes` BIGINT NOT NULL, `provider` VARCHAR(24) NOT NULL, `providerReference` VARCHAR(191) NOT NULL, `providerData` TEXT NULL, `lastVerifiedAt` DATETIME(3) NULL, `status` VARCHAR(24) NOT NULL, `startsAt` DATETIME(3) NOT NULL, `expiresAt` DATETIME(3) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `VaultStorageEntitlement_providerReference_key`(`providerReference`), INDEX `VaultStorageEntitlement_userId_expiresAt_idx`(`userId`, `expiresAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `VaultUploadLedger` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `objectKey` VARCHAR(1024) NOT NULL, `objectKeyHash` CHAR(64) NOT NULL, `sizeBytes` BIGINT NOT NULL, `state` VARCHAR(24) NOT NULL, `expiresAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `VaultUploadLedger_objectKeyHash_key`(`objectKeyHash`), INDEX `VaultUploadLedger_userId_state_idx`(`userId`, `state`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `VaultStoreConfig` (`id` INTEGER NOT NULL DEFAULT 1, `appleIssuerId` VARCHAR(191) NULL, `appleKeyId` VARCHAR(191) NULL, `applePrivateKeyEncrypted` TEXT NULL, `androidAppLinkSha256` TEXT NULL, `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
